import { PanelHeader, IconButton, Card } from "march/ui"
import { music, shuffle } from "march/icons"

// çalma listesi paneli: koyu zeminde ikonlu başlık, şarkı sayısı, karıştır düğmesi
export function MusicPanel() {
  let $shuffle = false
  return <Card m:theme="night">
    <PanelHeader icon={music} m:color="brand-pink" title="Gece Yolu" subtitle="Çalma listesi" meta={<span>12 şarkı</span>}
      actions={<IconButton icon={shuffle} label="Karıştır" pressed={$shuffle} on:click={() => $shuffle = !$shuffle} />} close={false} />
    <p sx={{ p: 2, text: "sm" }}>{$shuffle ? "Karışık çalıyor" : "Sırayla çalıyor"}</p>
  </Card>
}

import { PanelHeader, Badge, Button } from "march/ui"
import { settings, minus } from "march/icons"

// PanelHeader'ın özellikleri: as, lead, icon, title, titleAs, titleId, subtitle, meta, actions, onClose, close,
// closeLabel, size, sticky, divider, tone, drag, align, class
export function PanelHeaderLab() {
  let $closed = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <PanelHeader class="lab-head" icon={settings} title="Ayarlar" titleAs="h2" titleId="lab-title" subtitle="Çalışma alanı" meta={<Badge>3</Badge>}
      actions={<Button size="sm">Kaydet</Button>} onClose={() => $closed++} closeLabel="Paneli kapat" size="lg" divider tone="muted" sticky align="center" />
    <PanelHeader class="lab-own" lead={<span>☰</span>} title="Kendi kapat ikonum" close={minus} closeLabel="Küçült" onClose={() => $closed++} drag size="sm" />
    <PanelHeader class="lab-foot" as="footer" title="Alt çubuk" close={false} />
    <span class="lab-closed">{$closed} kez kapatıldı</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PanelHeaderLab } from "./PanelHeaderLab.tsx"

// PanelHeaderLab'in testleri: kaydedince Testler sekmesinde çalışır
test("titleAs ve titleId başlık öğesini belirler", () => {
  const s = renderTest(() => <PanelHeaderLab />)
  const t = s.get("#lab-title")
  expect(t?.tagName).toBe("H2")
  expect(t?.textContent).toBe("Ayarlar")
})

test("kapat düğmesi closeLabel adıyla onClose'u çağırır", async () => {
  const s = renderTest(() => <PanelHeaderLab />)
  await s.click("Paneli kapat")
  await s.click("Küçült")
  expect(s.get(".lab-closed")?.textContent).toBe("2 kez kapatıldı")
})

test("as=footer bir footer çizer", () => {
  const s = renderTest(() => <PanelHeaderLab />)
  expect(s.get(".lab-foot")?.tagName).toBe("FOOTER")
})
